}

export interface PayOrderResponse {
  /** integer(64,signed) */
  movement: number
  /** text(var,120,iso8859-1) */
  message: string
}

export interface Api {
  /** Debits the account of the company for one payment order and charges the commission. (rules RULE-001, RULE-002, RULE-003, RULE-004, RULE-005, RULE-006, RULE-007, RULE-008, RULE-009) */
  payOrder(request: PayOrderRequest): Promise<PayOrderResponse>
}

/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */
export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init)): Api {
  return {
    payOrder: (request) => call<PayOrderResponse>(fetchImpl, baseUrl, 'POST', '/api/payments/orders/pay', request, true),
  }
}
