import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Msg = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;
type Errors = Record<string, string>;

const onlyDigits = (v: string, max: number) => v.replace(/\D/g, '').slice(0, max);

// Format 9(9)V99: up to 9 integer digits and 2 decimals
const decimalInput = (v: string) => {
  const cleaned = v.replace(',', '.').replace(/[^\d.]/g, '');
  const [int = '', ...rest] = cleaned.split('.');
  const intPart = int.slice(0, 9);
  if (rest.length === 0) return intPart;
  return `${intPart}.${rest.join('').slice(0, 2)}`;
};

const CHANNELS = [
  { value: 'WEB', label: 'WEB - Canal web' },
  { value: 'OFI', label: 'OFI - Oficina' },
];

// Right alignment for the monetary value (label, input and hint)
const RIGHT_ALIGN_CSS = `
.pago-valor-right { text-align: right; }
.pago-valor-right input { text-align: right; font-variant-numeric: tabular-nums; }
`;

export default function PagoOrdenes({ navigate }: { navigate: (to: string) => void }) {
  const [orden, setOrden] = useState('');
  const [empresa, setEmpresa] = useState('');
  const [servic, setServic] = useState('');
  const [tipcta, setTipcta] = useState('');
  const [cuenta, setCuenta] = useState('');
  const [valor, setValor] = useState('');
  const [canal, setCanal] = useState('WEB');
  const [clave, setClave] = useState('');
  const [errors, setErrors] = useState<Errors>({});
  const [mensaje, setMensaje] = useState<Msg>(null);
  const [paid, setPaid] = useState(false);

  const reset = () => {
    setOrden('');
    setEmpresa('');
    setServic('');
    setTipcta('');
    setCuenta('');
    setValor('');
    setCanal('WEB');
    setClave('');
    setErrors({});
    setPaid(false);
  };

  const loadSample = () => {
    setOrden('1004582');
    setEmpresa('00231');
    setServic('ENERGIA');
    setTipcta('AHO');
    setCuenta('4501237890');
    setValor('125000.50');
    setCanal('WEB');
    setClave('483920');
    setErrors({});
    setPaid(false);
    setMensaje({ tone: 'info', text: 'Datos de ejemplo cargados. Pulse Pagar (ENTER) para continuar.' });
  };

  const pagar = () => {
    const e: Errors = {};
    if (!orden) e.ORDEN = 'El número de orden es obligatorio.';
    if (!empresa) e.EMPRESA = 'La empresa es obligatoria.';
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setPaid(false);
      setMensaje({ tone: 'error', text: 'Corrija los campos obligatorios marcados con * antes de pagar.' });
      return;
    }
    setPaid(true);
    setMensaje({ tone: 'success', text: `Pago de la orden ${orden} enviado correctamente.` });
  };

  const cancelar = () => {
    reset();
    setMensaje({ tone: 'info', text: 'Operación cancelada. Se limpiaron los campos del formulario.' });
  };

  const volver = () => navigate('SCR-PAGOMEN');

  return (
    <Screen
      title="Pago de órdenes"
      code="PAGOORD"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Pagar', onPress: pagar, primary: true },
            { key: 'PF3', label: 'Volver', onPress: volver },
            { key: 'PF12', label: 'Cancelar', onPress: cancelar },
          ]}
        />
      }
    >
      <style>{RIGHT_ALIGN_CSS}</style>
      <Stack>
        <div data-field="MENSAJE" aria-live="polite">
          {mensaje ? (
            <Alert tone={mensaje.tone}>
              {mensaje.text}
              {paid && mensaje.tone === 'success' && (
                <>
                  {' '}
                  <Button variant="secondary" onClick={() => navigate('SCR-PAGORES')}>
                    Ver resultado del pago
                  </Button>
                </>
              )}
            </Alert>
          ) : null}
        </div>

        <Card
          title="Datos de la orden"
          actions={
            <Button variant="ghost" onClick={loadSample}>
              Cargar datos de ejemplo
            </Button>
          }
        >
          <Grid columns={2}>
            <div data-field="ORDEN">
              <TextField
                label="Número de orden"
                required
                numeric
                maxLength={7}
                hint="Hasta 7 dígitos"
                error={errors.ORDEN}
                value={orden}
                onChange={(v: string) => setOrden(onlyDigits(v, 7))}
              />
            </div>
            <div data-field="EMPRESA">
              <TextField
                label="Empresa"
                required
                numeric
                maxLength={5}
                hint="Hasta 5 dígitos"
                error={errors.EMPRESA}
                value={empresa}
                onChange={(v: string) => setEmpresa(onlyDigits(v, 5))}
              />
            </div>
            <div data-field="SERVIC">
              <TextField
                label="Servicio"
                maxLength={10}
                hint="Máximo 10 caracteres"
                value={servic}
                onChange={(v: string) => setServic(v.toUpperCase().slice(0, 10))}
              />
            </div>
            <div data-field="CANAL">
              <SelectField
                label="Canal (WEB/OFI)"
                options={CHANNELS}
                hint="Valor inicial: WEB"
                value={canal}
                onChange={(v: string) => setCanal(v)}
              />
            </div>
            <div data-field="VALOR" className="pago-valor-right">
              <TextField
                label="Valor"
                numeric
                maxLength={12}
                hint="Hasta 9 enteros y 2 decimales"
                value={valor}
                onChange={(v: string) => setValor(decimalInput(v))}
              />
            </div>
          </Grid>
        </Card>

        <Card title="Cuenta y aprobación">
          <Stack>
            <Grid columns={2}>
              <div data-field="TIPCTA">
                <TextField
                  label="Tipo de cuenta"
                  maxLength={3}
                  hint="Ej.: AHO, CTE"
                  value={tipcta}
                  onChange={(v: string) => setTipcta(v.toUpperCase().slice(0, 3))}
                />
              </div>
              <div data-field="CUENTA">
                <TextField
                  label="Cuenta"
                  numeric
                  maxLength={10}
                  hint="Hasta 10 dígitos"
                  value={cuenta}
                  onChange={(v: string) => setCuenta(onlyDigits(v, 10))}
                />
              </div>
              <div data-field="CLAVE">
                <Stack>
                  <label htmlFor="clave-aprobacion">Clave de aprobación</label>
                  <input
                    id="clave-aprobacion"
                    type="password"
                    autoComplete="off"
                    maxLength={6}
                    value={clave}
                    onChange={(ev) => setClave(ev.target.value.slice(0, 6))}
                    aria-describedby="clave-hint"
                  />
                  <small id="clave-hint">Hasta 6 caracteres. El contenido se oculta al escribir.</small>
                </Stack>
              </div>
            </Grid>

            <small>Los campos con * son obligatorios.</small>

            <Row>
              <Button variant="primary" shortcut="ENTER" onClick={pagar}>
                Pagar
              </Button>
              <Button variant="danger" shortcut="PF12" onClick={cancelar}>
                Cancelar
              </Button>
              <Button variant="ghost" shortcut="PF3" onClick={volver}>
                Volver
              </Button>
            </Row>
          </Stack>
        </Card>
      </Stack>
    </Screen>
  );
}
