```tsx
import { useState } from 'react'
import type { FormEvent } from 'react'
import { Screen, Card, Grid, Stack, TextField, Button, Alert } from '@nexti/ds'
import { ApiError } from '../api/client'
import type { PayOrderRequest } from '../api/client'
import type { ScreenProps } from './types'

type Tone = 'info' | 'success' | 'warning' | 'error'
type Msg = { tone: Tone; text: string } | null
type Errors = Record<string, string>

const onlyDigits = (v: string, max: number) => v.replace(/\D/g, '').slice(0, max)

// Amount: digits with an optional decimal part, at most 11 characters
const amountInput = (v: string, max: number) => {
  const cleaned = v.replace(',', '.').replace(/[^\d.]/g, '')
  const [int = '', ...rest] = cleaned.split('.')
  const text = rest.length === 0 ? int : `${int}.${rest.join('').slice(0, 4)}`
  return text.slice(0, max)
}

const pad = (n: number) => String(n).padStart(2, '0')

// Local timestamp without time zone, e.g. 2024-05-31T14:03:09
const localTimestamp = (d: Date) =>
  `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`

export default function PagoordScreen({ api, navigate }: ScreenProps) {
  const [orden, setOrden] = useState('')
  const [empresa, setEmpresa] = useState('')
  const [servic, setServic] = useState('')
  const [tipcta, setTipcta] = useState('')
  const [cuenta, setCuenta] = useState('')
  const [valor, setValor] = useState('')
  const [canal, setCanal] = useState('WEB')
  const [clave, setClave] = useState('')
  const [errors, setErrors] = useState<Errors>({})
  const [mensaje, setMensaje] = useState<Msg>(null)
  const [busy, setBusy] = useState(false)

  const cancelar = () => {
    setOrden('')
    setEmpresa('')
    setServic('')
    setTipcta('')
    setCuenta('')
    setValor('')
    setCanal('WEB')
    setClave('')
    setErrors({})
    setMensaje({ tone: 'info', text: 'Operación cancelada. Se limpiaron los campos del formulario.' })
  }

  const pagar = async (ev: FormEvent) => {
    ev.preventDefault()
    if (busy) return

    const e: Errors = {}
    if (!orden.trim()) e.ORDEN = 'El número de orden es obligatorio.'
    if (!empresa.trim()) e.EMPRESA = 'La empresa es obligatoria.'
    setErrors(e)
    if (Object.keys(e).length > 0) {
      setMensaje({ tone: 'error', text: 'Corrija los campos obligatorios antes de pagar.' })
      return
    }

    const request: PayOrderRequest = {
      orderNumber: Number(orden),
      company: Number(empresa),
      service: servic,
      accountType: tipcta,
      account: cuenta,
      amount: valor === '' || valor === '.' ? 0 : Number(valor),
      channel: canal,
      processingDate: localTimestamp(new Date()),
    }

    setBusy(true)
    setMensaje(null)
    try {
      const response = await api.payOrder(request)
      setMensaje({ tone: 'success', text: response.message })
    } catch (err) {
      const text =
        err instanceof ApiError
          ? err.message
          : 'No fue posible procesar el pago. Intente nuevamente.'
      setMensaje({ tone: 'error', text })
    } finally {
      setBusy(false)
    }
  }

  return (
    <Screen title="PAGO DE ORDENES">
      <form onSubmit={pagar} noValidate>
        <Stack>
          {mensaje ? (
            <Alert tone={mensaje.tone}>
              <p data-field="MENSAJE" aria-live="polite">
                {mensaje.text}
              </p>
            </Alert>
          ) : (
            <p data-field="MENSAJE" aria-live="polite"></p>
          )}

          <Card title="Datos de la orden">
            <Grid columns={2}>
              <div data-field="ORDEN">
                <TextField
                  label="ORDEN"
                  required
                  numeric
                  maxLength={7}
                  error={errors.ORDEN}
                  value={orden}
                  onChange={(v: string) => setOrden(onlyDigits(v, 7))}
                />
              </div>
              <div data-field="EMPRESA">
                <TextField
                  label="EMPRESA"
                  required
                  numeric
                  maxLength={5}
                  error={errors.EMPRESA}
                  value={empresa}
                  onChange={(v: string) => setEmpresa(onlyDigits(v, 5))}
                />
              </div>
              <div data-field="SERVIC">
                <TextField
                  label="SERVIC"
                  maxLength={10}
                  value={servic}
                  onChange={(v: string) => setServic(v.toUpperCase().slice(0, 10))}
                />
              </div>
              <div data-field="CANAL">
                <TextField
                  label="CANAL"
                  maxLength={3}
                  value={canal}
                  onChange={(v: string) => setCanal(v.toUpperCase().slice(0, 3))}
                />
              </div>
              <div data-field="VALOR">
                <TextField
                  label="VALOR"
                  numeric
                  maxLength={11}
                  value={valor}
                  onChange={(v: string) => setValor(amountInput(v, 11))}
                />
              </div>
            </Grid>
          </Card>

          <Card title="Cuenta y aprobación">
            <Grid columns={2}>
              <div data-field="TIPCTA">
                <TextField
                  label="TIPCTA"
                  maxLength={3}
                  value={tipcta}
                  onChange={(v: string) => setTipcta(v.toUpperCase().slice(0, 3))}
                />
              </div>
              <div data-field="CUENTA">
                <TextField
                  label="CUENTA"
                  numeric
                  maxLength={10}
                  value={cuenta}
                  onChange={(v: string) => setCuenta(onlyDigits(v, 10))}
                />
              </div>
              <div data-field="CLAVE">
                <TextField
                  label="CLAVE"
                  type="password"
                  maxLength={6}
                  value={clave}
                  onChange={(v: string) => setClave(v.slice(0, 6))}
                />
              </div>
            </Grid>
          </Card>

          <Stack>
            <Button data-action="ENTER" type="submit" variant="primary" disabled={busy}>
              PAGAR
            </Button>
            <Button
              data-action="PF3"
              type="button"
              variant="ghost"
              onClick={() => navigate('SCR-PAGOMEN')}
            >
              VOLVER
            </Button>
            <Button data-action="PF12" type="button" variant="danger" onClick={cancelar}>
              CANCELAR
            </Button>
          </Stack>
        </Stack>
      </form>
    </Screen>
  )
}
```
